def connectivity(copper):
    bounds=[a['geometry'].bounds for a in copper]
    parent=list(range(len(copper)))
    def find(i):
        while parent[i]!=i:i=parent[i]
        return i
    shorts=[]
    for i,a in enumerate(copper):
        for j in range(i):
            z=copper[j]
            aa,bb=bounds[i],bounds[j]
            if aa[0]-bb[2]>.000002 or bb[0]-aa[2]>.000002 or aa[1]-bb[3]>.000002 or bb[1]-aa[3]>.000002:continue
            if not set(a['layers'])&set(z['layers']):continue
            if not a['geometry'].intersects(z['geometry']) and a['net']!=z['net'] and a['geometry'].distance(z['geometry'])<=.000002:
                raise AssertionError(('ambiguous near-contact below geometry resolution',a['id'],z['id']))
            if a['geometry'].intersects(z['geometry']):
                parent[find(i)]=find(j)
                if a['net']!=z['net'] or a['nc'] or z['nc']:shorts.append([a['id'],z['id'],a['net'],z['net']])
    groups={}
    for i,a in enumerate(copper):groups.setdefault(find(i),[]).append(a['id'])
    required={}
    for i,a in enumerate(copper):
        if a['pad'] and not a['nc']:required.setdefault(a['net'],set()).add(find(i))
    disconnected={n:len(v) for n,v in required.items() if len(v)>1}
    return shorts,groups,disconnected,find
